    // -----------------------------------------------------------------------
    // 批次B (#3/#11): editor candidate text rule — strict match + expected text
    // -----------------------------------------------------------------------

    fn ocr_line(rect: [i32; 4], text: &str, score: f32) -> oas_runtime::OcrLine {
        oas_runtime::OcrLine {
            rect: oas_types::Rect {
                x: rect[0],
                y: rect[1],
                w: rect[2],
                h: rect[3],
            },
            text: text.to_string(),
            score,
        }
    }

    fn candidate_texts(lines: &[oas_runtime::OcrLine]) -> Vec<&str> {
        lines.iter().map(|line| line.text.as_str()).collect()
    }

    #[test]
    fn candidate_ocr_filter_uses_the_strict_match_rule() {
        // #11: 「队伍1」 must never offer 「队伍2」/「队伍3」/「队伍12」 as a
        // candidate, even though the runtime's fuzzy click/wait rule (1 edit)
        // would accept them.
        let lines = vec![
            ocr_line([10, 10, 40, 12], "队伍1", 0.90),
            ocr_line([10, 30, 40, 12], "队伍2", 0.99),
            ocr_line([10, 50, 40, 12], "队伍3", 0.97),
            ocr_line([10, 70, 40, 12], "队伍12", 0.96),
            // Normalized-equal variants ARE the same text: full-width digit /
            // inner whitespace are formatting, not a different line.
            ocr_line([10, 90, 40, 12], "队伍１", 0.91),
            ocr_line([10, 110, 40, 12], " 队伍 1 ", 0.89),
            // A CJK variant glyph is not the same normalized text, so the strict
            // candidate rule rejects it (the fuzzy runtime rule accepts 1 edit).
            ocr_line([10, 130, 40, 12], "召喚", 0.95),
        ];
        let filtered = filter_ocr_candidate_lines(lines.clone(), Some("队伍1"), 0.0);
        assert_eq!(
            candidate_texts(&filtered),
            vec!["队伍1", "队伍１", " 队伍 1 "],
            "strict candidates: only the same normalized text"
        );
        // The confidence threshold still applies on top of the text filter.
        let filtered = filter_ocr_candidate_lines(lines.clone(), Some("队伍1"), 0.90);
        assert_eq!(candidate_texts(&filtered), vec!["队伍1", "队伍１"]);
        // No expected text (plain OCR asset without `ocr_text`): every detected
        // line at/above the threshold stays a candidate, detection order kept.
        let all = filter_ocr_candidate_lines(lines, None, 0.90);
        assert_eq!(all.len(), 6, "{all:?}");
        assert_eq!(candidate_texts(&all)[0], "队伍1");
        // No line matches the expected text → empty candidate list (the caller
        // then reports a loud step failure; never a fuzzy fallback).
        assert!(filter_ocr_candidate_lines(
            vec![ocr_line([0, 0, 10, 10], "开始", 0.9)],
            Some("结束"),
            0.0
        )
        .is_empty());
    }

    #[test]
    fn candidate_expected_text_follows_the_asset_kind() {
        // ocr_var: the Studio-side default text (`runtime_text`), trimmed; blank =
        // no text filter (every detected line is a candidate).
        let mut var = oas_task::AssetDecl::ocr_var("O_full", "group", "御魂", None);
        assert_eq!(ocr_candidate_expected_text(&var).as_deref(), Some("御魂"));
        var.runtime_text = Some("  结界  ".to_string());
        assert_eq!(
            ocr_candidate_expected_text(&var).as_deref(),
            Some("结界"),
            "runtime_text is trimmed"
        );
        var.runtime_text = Some("   ".to_string());
        assert_eq!(ocr_candidate_expected_text(&var), None);
        // Plain OCR asset: its saved expected text (`ocr_text`), even when the
        // asset is an `ocr_lines` row (batch B opens that field up).
        let mut plain = oas_task::AssetDecl::template("I_line", [0, 0, 10, 10]);
        plain.kind = "ocr_lines".to_string();
        plain.ocr_text = Some("开始".to_string());
        assert_eq!(ocr_candidate_expected_text(&plain).as_deref(), Some("开始"));
        plain.ocr_text = Some(" ".to_string());
        assert_eq!(ocr_candidate_expected_text(&plain), None);
    }

    /// #6/#10 endpoint contract: `POST /task/asset/update` accepts a present-style
    /// recognition `polygon` (absent = unchanged, `null` = clear, array = set),
    /// validated by the same geometry rules as the save path. For OCR/ocr_var the
    /// recognition ROI is re-derived from the polygon bbox (mask and ROI can never
    /// disagree); a template only accepts a mask whose bbox equals its current
    /// ROI (moving it needs 覆盖保存/re-crop).
    #[test]
    fn asset_update_sets_clears_and_validates_the_recognition_polygon() {
        let td = TempDir::new("b-polygon-update");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_frames_dir(td.path().join("frames"))
            .with_assets_dir(td.path().join("assets"));
        make_task(&tasks_dir, "t1");
        // Template saves compare the frame against the bundle design resolution.
        let frame_id = upload_test_frame(&server, &Frame::new(1280, 720, vec![3u8; 1280 * 720 * 4]));
        let assets_path = tasks_dir.join("t1").join("assets.json");
        let update = |body: serde_json::Value| {
            let (status, out) = post_route(
                &server,
                "/task/asset/update",
                "application/json",
                body.to_string().as_bytes(),
            );
            (status, out)
        };
        let saved_asset = |id: &str| -> serde_json::Value {
            read_json(&assets_path)["items"]
                .as_array()
                .expect("items")
                .iter()
                .find(|a| a["id"] == id)
                .cloned()
                .unwrap_or_else(|| panic!("asset `{id}` missing"))
        };

        // --- OCR row: set → absent keeps → explicit null clears -----------------
        save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "行一", "kind": "ocr_line",
                "roi": [10, 10, 30, 12], "positions": [frame_id],
                "ocr_mode": "lines", "ocr_text": "开始",
            }),
        );
        let ocr_poly = serde_json::json!([[12, 12], [40, 12], [40, 30], [12, 30]]);
        let (status, out) = update(serde_json::json!({"task":"t1","id":"行一","polygon":ocr_poly}));
        assert!(status.contains("200"), "{status} {out}");
        let v: serde_json::Value = serde_json::from_str(&out).expect("set json");
        assert_eq!(v["ok"], true, "{out}");
        assert_eq!(v["item"]["polygon"], ocr_poly, "{out}");
        assert_eq!(
            v["item"]["roi"],
            serde_json::json!([12, 12, 29, 19]),
            "OCR roi is re-derived from the polygon bbox: {out}"
        );
        // Absent = unchanged: a threshold-only edit must keep the mask.
        let (status, out) = update(serde_json::json!({"task":"t1","id":"行一","threshold":0.5}));
        assert!(status.contains("200"), "{status} {out}");
        assert_eq!(saved_asset("行一")["polygon"], ocr_poly, "{out}");
        // Explicit null clears it.
        let (status, out) = update(
            serde_json::json!({"task":"t1","id":"行一","polygon":serde_json::Value::Null}),
        );
        assert!(status.contains("200"), "{status} {out}");
        let cleared: serde_json::Value = serde_json::from_str(&out).expect("clear json");
        assert!(cleared["item"].get("polygon").is_none(), "clear echo: {out}");
        assert!(saved_asset("行一").get("polygon").is_none(), "persisted clear");
        // Invalid polygons are loud 400s and write nothing.
        for bad in [
            serde_json::json!([[1, 1], [20, 1]]),                            // < 3 points
            serde_json::json!([[1, 1], [20, 1], [1, 1]]),                    // repeated vertex
            serde_json::json!([[2000, 2000], [2100, 2000], [2100, 2100]]),   // outside the frame
            serde_json::json!([[0, 0], [30, 30], [30, 0], [0, 30]]),         // self-intersecting
        ] {
            let (status, out) = update(serde_json::json!({"task":"t1","id":"行一","polygon":bad}));
            assert!(status.contains("400"), "{bad} => {status} {out}");
            assert!(out.contains("polygon"), "{out}");
        }
        assert!(
            saved_asset("行一").get("polygon").is_none(),
            "rejected polygons must not be persisted"
        );

        // --- template: bbox must equal the existing ROI ------------------------
        save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "I_button", "kind": "template",
                "roi": [10, 10, 20, 10], "positions": [frame_id],
            }),
        );
        // This mask's bbox is exactly [10,10,20,10] (inclusive pixel bbox).
        let tpl_poly = serde_json::json!([[10, 10], [29, 10], [29, 19], [10, 19]]);
        let (status, out) = update(serde_json::json!({"task":"t1","id":"I_button","polygon":tpl_poly}));
        assert!(status.contains("200"), "{status} {out}");
        assert_eq!(
            saved_asset("I_button")["polygon"],
            tpl_poly,
            "template polygon set"
        );
        // A polygon that would move the recognition box needs a full overwrite.
        let (status, out) = update(serde_json::json!({
            "task":"t1","id":"I_button",
            "polygon":[[12, 12], [40, 12], [40, 30], [12, 30]],
        }));
        assert!(status.contains("400"), "{status} {out}");
        assert!(out.contains("must keep the existing ROI"), "{out}");
        // Clearing the mask keeps the template ROI untouched.
        let (status, _out) = update(
            serde_json::json!({"task":"t1","id":"I_button","polygon":serde_json::Value::Null}),
        );
        assert!(status.contains("200"), "{status} {_out}");
        let tpl = saved_asset("I_button");
        assert!(tpl.get("polygon").is_none(), "{tpl}");
        assert_eq!(tpl["roi"], serde_json::json!([10, 10, 20, 10]), "{tpl}");

        // --- ocr_var: whole-screen initially, polygon gives it a mask/ROI ------
        save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "O_full", "kind": "ocr_var",
                "runtime_text": "御魂", "param_key": "group", "positions": [frame_id],
            }),
        );
        let var_poly = serde_json::json!([[5, 5], [20, 5], [20, 15], [5, 15]]);
        let (status, out) = update(serde_json::json!({"task":"t1","id":"O_full","polygon":var_poly}));
        assert!(status.contains("200"), "{status} {out}");
        let var = saved_asset("O_full");
        assert_eq!(var["polygon"], var_poly, "{var}");
        assert_eq!(
            var["roi"],
            serde_json::json!([5, 5, 16, 11]),
            "ocr_var roi follows the mask bbox: {var}"
        );

        // --- region: no recognition polygon at all -----------------------------
        save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "R_area", "kind": "region",
                "roi": [5, 5, 10, 10], "positions": [frame_id],
            }),
        );
        let (status, out) = update(serde_json::json!({
            "task":"t1","id":"R_area","polygon":var_poly,
        }));
        assert!(status.contains("400"), "{status} {out}");
        assert!(out.contains("no recognition polygon"), "{out}");
    }

    /// Fake det+rec provider for the editor candidate-index test: the default
    /// build has no models, so the test seam returns fixed lines for any ROI.
    struct FakeOcrLines {
        lines: Vec<oas_runtime::OcrLine>,
    }

    impl oas_runtime::OcrProvider for FakeOcrLines {
        fn recognize(
            &mut self,
            _frame: &Frame,
            _roi: oas_types::Rect,
        ) -> Result<(String, f32), String> {
            let line = self
                .lines
                .first()
                .cloned()
                .ok_or_else(|| "fake OCR: no line".to_string())?;
            Ok((line.text, line.score))
        }

        fn recognize_lines(
            &mut self,
            _frame: &Frame,
            _roi: oas_types::Rect,
        ) -> Result<Vec<oas_runtime::OcrLine>, String> {
            Ok(self.lines.clone())
        }
    }

    #[test]
    fn test_action_candidate_index_selects_a_det_rec_candidate_of_a_plain_ocr_row() {
        // 批次B (#3): a plain `ocr_line` root must expose the SAME det+rec
        // multi-candidate list as `GET /task/asset/candidates`, and
        // `candidate_index >= 1` must be selectable (the historical single-line
        // path only ever read one crop, so index 1 was impossible).
        let td = TempDir::new("b-candidate-index-ocr");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_frames_dir(td.path().join("frames"))
            .with_assets_dir(td.path().join("assets"));
        make_task(&tasks_dir, "t1");
        let frame_id = upload_test_frame(&server, &Frame::new(64, 48, vec![9u8; 64 * 48 * 4]));
        save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "行一", "kind": "ocr_line",
                "roi": [0, 0, 64, 48], "positions": [frame_id],
                "ocr_mode": "lines", "ocr_text": "开始",
            }),
        );
        let lines = vec![
            ocr_line([10, 10, 20, 10], "开始", 0.90),
            ocr_line([10, 40, 20, 10], "开始", 0.80),
            // Different text: filtered out by the saved expected text, so the
            // candidate list has 2 entries, not 3.
            ocr_line([10, 30, 20, 10], "结束", 0.99),
        ];
        let server =
            server.with_ocr_override(move || Box::new(FakeOcrLines { lines: lines.clone() }));
        // index 1 = the lower-score matching line (order: score desc → y → x).
        let (status, v) = post_test_action(
            &server,
            serde_json::json!({"task":"t1","id":"行一","candidate_index":1}),
        );
        assert!(status.contains("200"), "{status} {v}");
        assert_eq!(v["real_rect"], serde_json::json!([10, 40, 20, 10]), "{v}");
        assert_eq!(v["action_box"], serde_json::json!([10, 40, 20, 10]), "{v}");
        assert_eq!(v["chain_depth"], 1, "{v}");
        assert_eq!(v["steps"][0]["text"], "开始", "{v}");
        // index 0 = the higher-score occurrence.
        let (status, v) = post_test_action(
            &server,
            serde_json::json!({"task":"t1","id":"行一","candidate_index":0}),
        );
        assert!(status.contains("200"), "{status} {v}");
        assert_eq!(v["real_rect"], serde_json::json!([10, 10, 20, 10]), "{v}");
        // The expected text keeps the list at 2 candidates → index 2 is loud.
        let (status, v) = post_test_action(
            &server,
            serde_json::json!({"task":"t1","id":"行一","candidate_index":2}),
        );
        assert!(status.contains("400"), "{status} {v}");
        assert!(
            v["errors"][0].as_str().unwrap_or("").contains("out of range"),
            "{v}"
        );
    }

    #[test]
    fn test_action_uses_variable_defaults_for_the_ocr_expected_text() {
        // V2.0b item 4: the Studio dry-run injects `meta.variables` defaults
        // (`variable_defaults`) — the retired `meta.params` is not read. A
        // variable whose key equals the ocr_var's `param_key` overrides its
        // `runtime_text` through the injection map (the same layer a Runner value
        // uses), so the preview must recognize the overridden text.
        let td = TempDir::new("v2b-test-action-vars");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_frames_dir(td.path().join("frames"))
            .with_assets_dir(td.path().join("assets"));
        make_task(&tasks_dir, "t1");
        let frame_id = upload_test_frame(&server, &Frame::new(64, 48, vec![6u8; 64 * 48 * 4]));
        save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "O_group", "kind": "ocr_var",
                "runtime_text": "御魂", "param_key": "group", "positions": [frame_id],
            }),
        );
        write_config_task(
            &tasks_dir,
            "t1",
            serde_json::json!({
                "schema_version": 1,
                "name": "t1",
                "variables": [{"key": "group", "type": "string", "default": "结界"}],
                "exits": {"done": {"result": "success"}, "failed": {"result": "retryable"}}
            }),
        );
        let lines = vec![
            // Higher score but NOT the injected text (the runtime_text default).
            ocr_line([10, 10, 20, 10], "御魂", 0.99),
            ocr_line([10, 40, 20, 10], "结界", 0.90),
        ];
        let server =
            server.with_ocr_override(move || Box::new(FakeOcrLines { lines: lines.clone() }));
        let (status, v) =
            post_test_action(&server, serde_json::json!({"task":"t1","id":"O_group"}));
        assert!(status.contains("200"), "{status} {v}");
        assert_eq!(
            v["real_rect"],
            serde_json::json!([10, 40, 20, 10]),
            "the variable default must drive the expected text: {v}"
        );
        assert_eq!(v["steps"][0]["text"], "结界", "{v}");
    }

    /// #3 candidate alignment: batch B opens `ocr_text` (expected text) up to
    /// plain `ocr_lines` rows, so the same asset can act as an `op_region`
    /// recognition gate. The save route must pass it through and the candidate
    /// expected-text rule must pick it up without any `ocr_mode` marker.
    #[test]
    fn save_asset_accepts_expected_text_on_a_plain_ocr_lines_row() {
        let (_td, server, _tasks_dir, frame_id) = acceptance9_server("b-ocr-lines-text");
        let v = save_asset_route(
            &server,
            serde_json::json!({
                "task": "t1", "id": "行组", "kind": "ocr_lines",
                "roi": [0, 0, 64, 48], "positions": [frame_id],
                "ocr_text": "开始",
            }),
        );
        assert_eq!(v["item"]["kind"], "ocr_lines", "{v}");
        assert_eq!(v["item"]["ocr_text"], "开始", "{v}");
        assert!(
            v["item"].get("ocr_mode").is_none(),
            "a plain ocr_lines row needs no ocr_mode marker: {v}"
        );
        // GET /task/assets round-trips the expected text; the candidate
        // expected-text rule (shared by the OCR branch) uses it directly.
        let assets = get_json_route(&server, "/task/assets?task=t1");
        let item = assets["items"]
            .as_array()
            .expect("items")
            .iter()
            .find(|a| a["id"] == "行组")
            .expect("ocr_lines row");
        assert_eq!(item["ocr_text"], "开始", "{assets}");
    }

    #[test]
    fn save_assets_batch_persists_ocr_polygons() {
        let td = TempDir::new("batch-ocr-polygon");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_frames_dir(td.path().join("frames"))
            .with_assets_dir(td.path().join("assets"));
        make_task(&tasks_dir, "t1");
        let frame_id = upload_test_frame(&server, &Frame::new(64, 48, vec![128u8; 64 * 48 * 4]));
        let payload = serde_json::json!({
            "task": "t1",
            "assets": [
                {
                    "id": "行一",
                    "kind": "ocr_line",
                    "roi": [10, 10, 30, 12],
                    "positions": [frame_id],
                    "ocr_mode": "lines",
                    "ocr_text": "开始",
                    "polygon": [[12, 12], [40, 12], [40, 30], [12, 30]],
                    "action_shape": {"kind": "rect", "roi": [12, 12, 29, 19], "invert": false},
                    "action_source": "fixed",
                },
                {
                    "id": "行二",
                    "kind": "ocr_line",
                    "roi": [5, 5, 20, 10],
                    "positions": [frame_id],
                    "ocr_mode": "lines",
                    "ocr_text": "结束",
                    "polygon": [[6, 6], [24, 6], [24, 16], [6, 16]],
                    "action_shape": {"kind": "rect", "roi": [6, 6, 19, 11], "invert": false},
                    "action_source": "fixed",
                }
            ]
        });
        let (status, out) = post_route(
            &server,
            "/task/save_assets",
            "application/json",
            payload.to_string().as_bytes(),
        );
        assert!(status.contains("200"), "{status} {out}");
        let v: serde_json::Value = serde_json::from_str(&out).expect("batch json");
        let saved = v["saved"].as_array().expect("saved");
        assert_eq!(saved.len(), 2, "{out}");
        let expected = [
            (
                "行一",
                "开始",
                serde_json::json!([[12, 12], [40, 12], [40, 30], [12, 30]]),
                serde_json::json!([12, 12, 29, 19]),
            ),
            (
                "行二",
                "结束",
                serde_json::json!([[6, 6], [24, 6], [24, 16], [6, 16]]),
                serde_json::json!([6, 6, 19, 11]),
            ),
        ];
        for (item, (id, text, poly, roi)) in saved.iter().zip(expected) {
            assert_eq!(item["id"], id, "{out}");
            assert_eq!(item["ocr_mode"], "lines", "{out}");
            assert_eq!(item["ocr_text"], text, "{out}");
            assert_eq!(item["polygon"], poly, "{out}");
            assert_eq!(item["roi"], roi, "{out}");
            // The operation shape rides along; the deprecated two-state field
            // is ignored on input and never echoed back (P0b).
            assert!(item.get("action_source").is_none(), "{out}");
            assert_eq!(item["action_shape"]["kind"], "rect", "{out}");
        }
        let persisted = read_json(&tasks_dir.join("t1").join("assets.json"));
        let items = persisted["items"].as_array().expect("items");
        assert_eq!(items.len(), 2);
        assert!(
            items.iter().all(|a| a["ocr_mode"] == "lines"
                && a["polygon"].is_array()
                && a.get("action_source").is_none()),
            "the deprecated field must not be persisted: {persisted}"
        );
    }

    #[test]
    fn save_asset_rejects_an_invalid_polygon() {
        let td = TempDir::new("save-bad-polygon");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_frames_dir(td.path().join("frames"))
            .with_assets_dir(td.path().join("assets"));
        make_task(&tasks_dir, "t1");
        let frame_id = upload_test_frame(&server, &Frame::new(64, 48, vec![0u8; 64 * 48 * 4]));
        let base = serde_json::json!({
            "task": "t1",
            "id": "坏多边形",
            "kind": "ocr_line",
            "roi": [4, 4, 20, 10],
            "positions": [frame_id],
        });
        let cases = [
            // JSON-shape errors (serve layer).
            (
                serde_json::json!("not-an-array"),
                "must be an array of [x,y] integer pairs",
            ),
            (
                serde_json::json!([[1, 2, 3]]),
                "must be an [x,y] pair of integers",
            ),
            // Geometry errors (oas-task: >= 3 points, inside the frame).
            (serde_json::json!([[1, 1], [10, 10]]), ">= 3 points"),
            (
                serde_json::json!([[0, 0], [100, 0], [100, 100]]),
                "outside the 64x48 frame",
            ),
        ];
        for (polygon, expected) in cases {
            let mut payload = base.clone();
            payload["polygon"] = polygon.clone();
            let (status, out) = post_route(
                &server,
                "/task/save_asset",
                "application/json",
                payload.to_string().as_bytes(),
            );
            assert!(
                status.contains("400"),
                "polygon={polygon} => {status} {out}"
            );
            assert!(out.contains(expected), "polygon={polygon} => {out}");
        }
        // Rejected saves write nothing.
        let assets = read_json(&tasks_dir.join("t1").join("assets.json"));
        assert_eq!(
            assets["items"].as_array().map(|a| a.len()),
            Some(0),
            "{assets}"
        );
    }

    #[test]
    fn save_assets_batch_rejects_an_invalid_polygon() {
        let td = TempDir::new("batch-bad-polygon");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_frames_dir(td.path().join("frames"))
            .with_assets_dir(td.path().join("assets"));
        make_task(&tasks_dir, "t1");
        let frame_id = upload_test_frame(&server, &Frame::new(64, 48, vec![0u8; 64 * 48 * 4]));
        // Parse-level rejection: the item index must be reported.
        let bad_shape = serde_json::json!({
            "task": "t1",
            "assets": [{
                "id": "坏多边形",
                "kind": "ocr_line",
                "roi": [4, 4, 20, 10],
                "positions": [frame_id],
                "polygon": "nope",
            }]
        });
        let (status, out) = post_route(
            &server,
            "/task/save_assets",
            "application/json",
            bad_shape.to_string().as_bytes(),
        );
        assert!(status.contains("400"), "{status} {out}");
        assert!(out.contains("assets[0].polygon"), "{out}");
        // Geometry rejection: oas-task owns the polygon rules.
        let bad_geometry = serde_json::json!({
            "task": "t1",
            "assets": [{
                "id": "坏多边形",
                "kind": "ocr_line",
                "roi": [4, 4, 20, 10],
                "positions": [frame_id],
                "ocr_mode": "lines",
                "ocr_text": "坏",
                "polygon": [[1, 1], [20, 1]],
            }]
        });
        let (status, out) = post_route(
            &server,
            "/task/save_assets",
            "application/json",
            bad_geometry.to_string().as_bytes(),
        );
        assert!(status.contains("400"), "{status} {out}");
        assert!(out.contains("polygon needs >= 3 points"), "{out}");
        // A rejected batch writes nothing (all-or-nothing).
        let assets = read_json(&tasks_dir.join("t1").join("assets.json"));
        assert_eq!(
            assets["items"].as_array().map(|a| a.len()),
            Some(0),
            "{assets}"
        );
    }

    #[test]
    fn optional_ocr_and_polygon_fields_parse_strictly() {
        let v = serde_json::json!({
            "ocr_mode": "lines",
            "ocr_text": "开始",
            "ocr_source_roi": [1, 2, 30, 40],
        });
        assert_eq!(
            json_opt_str_field(&v, "ocr_mode").unwrap().as_deref(),
            Some("lines")
        );
        assert_eq!(
            json_opt_str_field(&v, "ocr_text").unwrap().as_deref(),
            Some("开始")
        );
        assert_eq!(
            json_opt_roi_field(&v, "ocr_source_roi").unwrap(),
            Some([1, 2, 30, 40])
        );
        // Absent/null = unused (the editor may send null explicitly).
        let empty = serde_json::json!({
            "ocr_mode": null,
            "polygon": null,
            "ocr_source_roi": null,
        });
        assert_eq!(json_opt_str_field(&empty, "ocr_mode").unwrap(), None);
        assert_eq!(json_opt_polygon_field(&empty, "polygon").unwrap(), None);
        assert_eq!(json_opt_roi_field(&empty, "ocr_source_roi").unwrap(), None);
        // Wrong types are errors, never silently dropped.
        let bad = serde_json::json!({
            "ocr_mode": 1,
            "polygon": "x",
            "ocr_source_roi": [1, 2, 3],
        });
        assert!(json_opt_str_field(&bad, "ocr_mode")
            .unwrap_err()
            .contains("must be a string"));
        assert!(json_opt_polygon_field(&bad, "polygon")
            .unwrap_err()
            .contains("must be an array"));
        assert!(json_opt_roi_field(&bad, "ocr_source_roi")
            .unwrap_err()
            .contains("4 integers"));
        // Out-of-i32 values must be rejected, not truncated.
        let huge = serde_json::json!({"ocr_source_roi": [0, 0, 4294967296i64, 10]});
        assert!(json_opt_roi_field(&huge, "ocr_source_roi")
            .unwrap_err()
            .contains("does not fit in i32"));
        let huge_poly = serde_json::json!({"polygon": [[0, 0], [10, 0], [10, 4294967296i64]]});
        assert!(json_opt_polygon_field(&huge_poly, "polygon").is_err());

        // Present-style (#9 replace inheritance / #10 update): absent, explicit
        // null and a value are three distinct states.
        assert_eq!(
            json_present_polygon_field(&serde_json::json!({}), "polygon").unwrap(),
            None,
            "absent must stay distinct from null"
        );
        assert_eq!(
            json_present_polygon_field(&empty, "polygon").unwrap(),
            Some(None),
            "explicit null means clear"
        );
        let three = serde_json::json!({"polygon": [[1, 2], [10, 2], [10, 8]]});
        assert_eq!(
            json_present_polygon_field(&three, "polygon").unwrap(),
            Some(Some(vec![[1, 2], [10, 2], [10, 8]])),
            "a present array is the new polygon"
        );
        assert!(json_present_polygon_field(&bad, "polygon")
            .unwrap_err()
            .contains("must be an array"));
    }

    #[test]
    fn asset_match_route_returns_400_for_invalid_frame_id() {
        let td = TempDir::new("frame-id-http");
        let tasks_dir = td.path().join("tasks");
        let server = server_with_tasks(td.path())
            .with_assets_dir(td.path().join("assets"))
            .with_live_capture(|| Err("no adb device attached (fake)".to_string()));
        make_task(&tasks_dir, "t1");
        let bundle = oas_task::TaskBundle::open_named(&tasks_dir, "t1").expect("bundle");
        // `make_task` authors the skeleton at 1280x720, so the template frame
        // must match the bundle design resolution.
        bundle
            .save_asset(
                oas_task::AssetDecl::template("tpl", [0, 0, 2, 2]),
                Some(&Frame::new(1280, 720, vec![255u8; 1280 * 720 * 4])),
            )
            .expect("template asset");

        for url in [
            "/task/asset/match?task=t1&id=tpl&frame_id=abc",
            "/task/asset/match?task=t1&id=tpl&frame_id=999",
            // live=1 must force a capture; a failure is a 400, never a stale
            // cached frame reported as a successful live test.
            "/task/asset/match?task=t1&id=tpl&live=1",
        ] {
            let (status, body) = get_route(&server, url);
            assert!(status.contains("400"), "{url} => {status} {body}");
            if url.contains("live=1") {
                assert!(body.contains("capture failed"), "{body}");
                assert!(body.contains("no adb device"), "{body}");
            }
        }
    }

    // -----------------------------------------------------------------------
    // P0a: `GET /task/asset/candidates` — every real recognition region + score
    // (docs/PARAM-ASSET-REDESIGN.md §1b item 3)
    // -----------------------------------------------------------------------

    /// Paint a `draw_w`x`draw_h` window out of one grayscale patch into an RGBA
    /// frame buffer. `patch_stride` is the patch's row length, so a sub-window
    /// of the same patch can be painted (e.g. template columns only).
    fn paint_gray_patch(
        rgba: &mut [u8],
        frame_w: u32,
        x: u32,
        y: u32,
        patch: &[u8],
        patch_stride: u32,
        draw_w: u32,
        draw_h: u32,
    ) {
        for py in 0..draw_h {
            for px in 0..draw_w {
                let v = patch[(py * patch_stride + px) as usize];
                let i = (((y + py) * frame_w + (x + px)) * 4) as usize;
                rgba[i] = v;
                rgba[i + 1] = v;
                rgba[i + 2] = v;
                rgba[i + 3] = 255;
            }
        }
    }

    /// Deterministic 8x8 pseudo-random texture (NCC only distinguishes textured
    /// patches; a flat patch is undefined and never matches).
    fn candidate_patch(seed: u32) -> Vec<u8> {
        let mut s = seed;
        (0..64)
            .map(|_| {
                s ^= s << 13;
                s ^= s >> 17;
                s ^= s << 5;
                (s & 0xff) as u8
            })
            .collect()
    }

    /// Deterministic 64x48 textured frame for the candidate tests:
    /// template patch `A` is painted at **(20,20)** and **(48,8)** (two exact
    /// occurrences, NCC 1.0), template patch `B` at **(40,30)** (one exact
    /// occurrence), and a **partly covered** copy of `A` (only its left 6 of 8
    /// columns — NCC ≈ 0.75) at **(10,36)**: it sits between the loose (0.6) and
    /// normal (0.9) thresholds, which is exactly what the threshold test needs.
    fn asset_candidates_frame() -> Frame {
        let (w, h) = (64u32, 48u32);
        let mut rgba = vec![0u8; (w * h * 4) as usize];
        let mut s: u32 = 0x1357_9BDF;
        for i in 0..(w * h) as usize {
            s ^= s << 13;
            s ^= s >> 17;
            s ^= s << 5;
            let v = (s & 0xff) as u8;
            rgba[i * 4] = v;
            rgba[i * 4 + 1] = v;
            rgba[i * 4 + 2] = v;
            rgba[i * 4 + 3] = 255;
        }
        let a = candidate_patch(0x0A0B_0C0D);
        let b = candidate_patch(0x0B0C_0D0E);
        paint_gray_patch(&mut rgba, w, 20, 20, &a, 8, 8, 8);
        paint_gray_patch(&mut rgba, w, 48, 8, &a, 8, 8, 8);
        paint_gray_patch(&mut rgba, w, 40, 30, &b, 8, 8, 8);
        paint_gray_patch(&mut rgba, w, 10, 36, &a, 8, 6, 8); // left 6 of 8 columns
        Frame::new(w, h, rgba)
    }

    /// Global-asset fixture for `GET /task/asset/candidates`: one 64x48 frame
    /// (uploaded through the real `/frames` route, so it is the current frame)
    /// and every asset shape the candidate tests need.
    fn asset_candidates_fixture(td: &Path) -> Server {
        let frame = asset_candidates_frame();
        let tpl_a = crop_frame(&frame, 20, 20, 8, 8);
        let tpl_b = crop_frame(&frame, 40, 30, 8, 8);
        // Anti-correlated copy of A: NCC -1, so it can never be a candidate.
        let mut anti = tpl_a.rgba.clone();
        for px in anti.chunks_exact_mut(4) {
            px[0] = 255 - px[0];
            px[1] = 255 - px[1];
            px[2] = 255 - px[2];
        }
        let tpl_never = Frame::new(8, 8, anti);
        let assets_dir = td.join("assets");
        std::fs::create_dir_all(assets_dir.join("images")).expect("assets images dir");
        for (name, tpl) in [
            ("a001.png", &tpl_a),
            ("a002.png", &tpl_b),
            ("a003.png", &tpl_never),
        ] {
            std::fs::write(
                assets_dir.join("images").join(name),
                oas_codec::encode_png(tpl).expect("template png"),
            )
            .expect("write template png");
        }
        let items = serde_json::json!([
            // Exact template A, whole-frame search window.
            {"id":"TPL","kind":"template","file":"images/a001.png","roi":[0,0,64,48],"threshold":0.9,"positions":[1]},
            // Same template without an ROI: the whole frame is searched.
            {"id":"TPL_NO_ROI","kind":"template","file":"images/a001.png","threshold":0.9,"positions":[1]},
            // Same template with a loose threshold: includes the weak match.
            {"id":"TPL_LOOSE","kind":"template","file":"images/a001.png","roi":[0,0,64,48],"threshold":0.6,"positions":[1]},
            // Narrow search window: only the (20,20) occurrence is inside it.
            {"id":"TPL_ROI","kind":"template","file":"images/a001.png","roi":[0,0,32,48],"threshold":0.9,"positions":[1]},
            // Exact operation shape: must be translated by the match offset.
            {"id":"TPL_SHAPE","kind":"template","file":"images/a001.png","roi":[0,0,64,48],"threshold":0.9,"positions":[1],
             "action_shape":{"kind":"rect","roi":[2,2,4,4],"invert":false},"action_source":"fixed"},
            // Never-present texture: proves the miss path returns 0 candidates.
            {"id":"MISS","kind":"template","file":"images/a003.png","roi":[0,0,64,48],"threshold":0.9,"positions":[1]},
            // Pure operation region: exactly one candidate, no frame needed.
            {"id":"REGION","kind":"region","roi":[5,5,10,10],"positions":[1]},
            // Collection members, declared in the REVERSE of the visual order.
            {"id":"M_A","kind":"template","file":"images/a001.png","roi":[0,0,64,48],"threshold":0.9,"positions":[1]},
            {"id":"M_B","kind":"template","file":"images/a002.png","roi":[0,0,64,48],"threshold":0.9,"positions":[1]},
            // OCR asset: the default build answers 501 (no feature/models); the
            // expected text needs `ocr_mode:"lines"` (批次B keeps det+rec rows as
            // the only carriers of `ocr_text`).
            {"id":"OCR_LINE","kind":"ocr_line","roi":[10,10,20,10],"ocr_mode":"lines","ocr_text":"开始","positions":[1]}
        ]);
        let collections = serde_json::json!([
            {"id":"COL","members":["M_B","M_A"],"threshold":0.9}
        ]);
        let assets = serde_json::json!({
            "schema_version": 1,
            "design_resolution": [64, 48],
            "items": items,
            "collections": collections
        });
        std::fs::write(assets_dir.join("assets.json"), assets.to_string())
            .expect("write global assets.json");
        let server = server_with_tasks(td)
            .with_frames_dir(td.join("frames"))
            .with_assets_dir(assets_dir);
        upload_test_frame(&server, &frame);
        server
    }

    #[test]
    fn asset_candidates_lists_every_template_match_in_stable_order() {
        let td = TempDir::new("cand-template");
        let server = asset_candidates_fixture(td.path());
        let v = get_json_route(&server, "/task/asset/candidates?id=TPL");
        assert_eq!(v["ok"], true, "{v}");
        assert_eq!(v["id"], "TPL", "{v}");
        assert_eq!(v["kind"], "template", "{v}");
        assert_eq!(v["count"], 2, "{v}");
        assert_eq!(v["frame_source"], "current", "{v}");
        assert_eq!(v["domain"], "roi", "{v}");
        assert_eq!(v["roi"], serde_json::json!([0, 0, 64, 48]), "{v}");
        assert!(v["threshold"].as_f64().expect("threshold") > 0.89, "{v}");
        assert!(v["elapsed_ms"].as_f64().is_some(), "{v}");
        let cands = v["candidates"].as_array().expect("candidates");
        assert_eq!(cands.len(), 2);
        // Both occurrences are exact copies (score 1.0); the documented tie
        // order is y asc then x asc, so (48,8) comes before (20,20).
        for (i, (x, y)) in [(48i64, 8i64), (20, 20)].into_iter().enumerate() {
            assert_eq!(cands[i]["index"], i, "{v}");
            assert_eq!(cands[i]["x"].as_i64(), Some(x), "{v}");
            assert_eq!(cands[i]["y"].as_i64(), Some(y), "{v}");
            assert_eq!(cands[i]["w"], 8, "{v}");
            assert_eq!(cands[i]["h"], 8, "{v}");
            assert_eq!(cands[i]["pass"], true, "{v}");
            assert!(
                cands[i]["score"].as_f64().expect("score") > 0.99,
                "{v}"
            );
            // No action_shape: the operation box is the matched template bbox.
            assert_eq!(cands[i]["action_box"], serde_json::json!([x, y, 8, 8]), "{v}");
            assert!(cands[i].get("text").is_none(), "no `text` for templates: {v}");
        }
    }

    #[test]
    fn asset_candidates_are_full_frame_even_with_an_authored_roi() {
        let td = TempDir::new("cand-roi");
        let server = asset_candidates_fixture(td.path());
        // 2026-11-06 seq127 #1: an authored ROI no longer limits candidate
        // enumeration — templates/collections are searched in the WHOLE frame
        // (the ROI is only a hint for the historical single-best click path).
        // `domain` still describes the declared domain for the editor UI; the
        // (48,8) occurrence outside [0,0,32,48] is now a candidate too.
        let v = get_json_route(&server, "/task/asset/candidates?id=TPL_ROI");
        assert_eq!(v["count"], 2, "{v}");
        assert_eq!(v["domain"], "roi", "{v}");
        let mut rows: Vec<(i64, i64)> = v["candidates"]
            .as_array()
            .expect("candidates")
            .iter()
            .map(|c| {
                (
                    c["x"].as_i64().expect("x"),
                    c["y"].as_i64().expect("y"),
                )
            })
            .collect();
        rows.sort_unstable();
        assert_eq!(rows, vec![(20, 20), (48, 8)], "{v}");
        // No ROI: the whole frame is searched as before (same two occurrences).
        let v = get_json_route(&server, "/task/asset/candidates?id=TPL_NO_ROI");
        assert_eq!(v["count"], 2, "{v}");
        assert_eq!(v["domain"], "screen", "{v}");
        assert_eq!(v["roi"], serde_json::Value::Null, "{v}");
    }

    #[test]
    fn asset_candidates_threshold_filters_weak_occurrences() {
        let td = TempDir::new("cand-threshold");
        let server = asset_candidates_fixture(td.path());
        // Normal threshold: the two exact occurrences only.
        let strict = get_json_route(&server, "/task/asset/candidates?id=TPL");
        assert_eq!(strict["count"], 2, "{strict}");
        assert!(
            strict["candidates"]
                .as_array()
                .expect("candidates")
                .iter()
                .all(|c| c["score"].as_f64().expect("score") >= 0.9),
            "{strict}"
        );
        // Loose threshold: the partly covered occurrence is now a candidate,
        // with a score between the two thresholds.
        let loose = get_json_route(&server, "/task/asset/candidates?id=TPL_LOOSE");
        assert!(loose["count"].as_u64().expect("count") > 2, "{loose}");
        assert!(
            loose["candidates"]
                .as_array()
                .expect("candidates")
                .iter()
                .any(|c| {
                    let score = c["score"].as_f64().unwrap_or(1.0);
                    (0.6..0.9).contains(&score)
                }),
            "the weak occurrence must appear only for the loose threshold: {loose}"
        );
        assert!(loose["threshold"].as_f64().expect("threshold") < 0.9, "{loose}");
        // A template that never appears has zero candidates (not an error).
        let miss = get_json_route(&server, "/task/asset/candidates?id=MISS");
        assert_eq!(miss["count"], 0, "{miss}");
        assert_eq!(
            miss["candidates"].as_array().map(|a| a.len()),
            Some(0),
            "{miss}"
        );
    }

    #[test]
    fn asset_candidates_collection_merges_members_and_sorts() {
        let td = TempDir::new("cand-collection");
        let server = asset_candidates_fixture(td.path());
        let v = get_json_route(&server, "/task/asset/candidates?id=COL");
        assert_eq!(v["kind"], "collection", "{v}");
        assert_eq!(v["domain"], "members", "{v}");
        assert_eq!(v["roi"], serde_json::Value::Null, "{v}");
        assert_eq!(v["count"], 3, "{v}");
        let cands = v["candidates"].as_array().expect("candidates");
        // Declaration order is [M_B, M_A], but the editor contract sorts by
        // score desc → y asc → x asc. All three are exact matches (score 1.0),
        // so y decides and the visual order wins over declaration order.
        let rows: Vec<(i64, i64, &str)> = cands
            .iter()
            .map(|c| {
                (
                    c["x"].as_i64().expect("x"),
                    c["y"].as_i64().expect("y"),
                    c["member"].as_str().expect("member"),
                )
            })
            .collect();
        assert_eq!(
            rows,
            vec![(48, 8, "M_A"), (20, 20, "M_A"), (40, 30, "M_B")],
            "{v}"
        );
        for (i, c) in cands.iter().enumerate() {
            assert_eq!(c["index"], i, "{v}");
            assert_eq!(c["pass"], true, "{v}");
            let x = c["x"].as_i64().expect("x");
            let y = c["y"].as_i64().expect("y");
            assert_eq!(c["action_box"], serde_json::json!([x, y, 8, 8]), "{v}");
        }
    }

    /// seq132: append a mixed collection (template + fixed region) to the global
    /// store created by [`asset_candidates_fixture`].
    fn add_mixed_collection(td: &Path, id: &str, members: &[&str]) {
        let path = td.join("assets/assets.json");
        let text = std::fs::read_to_string(&path).expect("read fixture assets");
        let mut v: serde_json::Value = serde_json::from_str(&text).expect("fixture JSON");
        v["collections"]
            .as_array_mut()
            .expect("collections")
            .push(serde_json::json!({
                "id": id,
                "members": members,
                "threshold": 0.9,
                "action_source": "recognition"
            }));
        std::fs::write(&path, v.to_string()).expect("write mixed collection");
    }

    #[test]
    fn asset_candidates_mixed_collection_lists_every_member_kind() {
        let td = TempDir::new("cand-col-mixed");
        let server = asset_candidates_fixture(td.path());
        add_mixed_collection(td.path(), "COL_MIX", &["M_A", "REGION"]);
        let v = get_json_route(&server, "/task/asset/candidates?id=COL_MIX");
        assert_eq!(v["kind"], "collection", "{v}");
        assert_eq!(v["domain"], "members", "{v}");
        // M_A has two exact occurrences + the fixed region = 3 candidates.
        assert_eq!(v["count"], 3, "{v}");
        let rows: Vec<(i64, i64, &str, &str)> = v["candidates"]
            .as_array()
            .expect("candidates")
            .iter()
            .map(|c| {
                (
                    c["x"].as_i64().expect("x"),
                    c["y"].as_i64().expect("y"),
                    c["member"].as_str().expect("member"),
                    c["member_kind"].as_str().expect("member_kind"),
                )
            })
            .collect();
        // Sorted score desc (all 1.0) → y asc: region y=5 first.
        assert_eq!(
            rows,
            vec![
                (5, 5, "REGION", "region"),
                (48, 8, "M_A", "template"),
                (20, 20, "M_A", "template"),
            ],
            "{v}"
        );
        for c in v["candidates"].as_array().expect("candidates") {
            assert_eq!(c["pass"], true, "{v}");
        }
        // The region candidate's action_box is its fixed ROI.
        assert_eq!(
            v["candidates"][0]["action_box"],
            serde_json::json!([5, 5, 10, 10]),
            "{v}"
        );
        // ...and test_action uses the SAME candidate list/order.
        let body = serde_json::json!({"id": "COL_MIX"}).to_string();
        let (status, out) = post_route(
            &server,
            "/task/asset/test_action",
            "application/json",
            body.as_bytes(),
        );
        assert!(status.contains("200"), "{status} {out}");
        let ta: serde_json::Value = serde_json::from_str(&out).expect("test_action json");
        assert_eq!(ta["action_box"], serde_json::json!([5, 5, 10, 10]), "{out}");
        assert_eq!(ta["steps"][0]["asset"], "REGION", "{out}");
        assert_eq!(ta["real"], false, "{out}");
        // candidate_index 1 = the second row of the candidate list (M_A at 48,8).
        let body = serde_json::json!({"id": "COL_MIX", "candidate_index": 1}).to_string();
        let (status, out) = post_route(
            &server,
            "/task/asset/test_action",
            "application/json",
            body.as_bytes(),
        );
        assert!(status.contains("200"), "{status} {out}");
        let ta: serde_json::Value = serde_json::from_str(&out).expect("test_action json");
        assert_eq!(ta["steps"][0]["asset"], "M_A", "{out}");
        assert_eq!(ta["action_box"], serde_json::json!([48, 8, 8, 8]), "{out}");
    }

