    #[test]
    fn asset_candidates_translate_the_action_shape_by_the_match_offset() {
        let td = TempDir::new("cand-shape");
        let server = asset_candidates_fixture(td.path());
        let v = get_json_route(&server, "/task/asset/candidates?id=TPL_SHAPE");
        assert_eq!(v["count"], 2, "{v}");
        let cands = v["candidates"].as_array().expect("candidates");
        // Authored shape [2,2,4,4] relative to the ROI origin (0,0); translated
        // by the match offset like the runtime click path does.
        assert_eq!(cands[0]["y"].as_i64(), Some(8), "{v}");
        assert_eq!(
            cands[0]["action_box"],
            serde_json::json!([50, 10, 4, 4]),
            "{v}"
        );
        assert_eq!(cands[1]["y"].as_i64(), Some(20), "{v}");
        assert_eq!(
            cands[1]["action_box"],
            serde_json::json!([22, 22, 4, 4]),
            "{v}"
        );
        // The candidate API and `test_action` MUST agree on the operation box:
        // both go through the shared model-A `self_operation_geometry` helper
        // (model A: the final box is the ROOT asset's own geometry).
        for (index, expected) in [
            (0usize, serde_json::json!([50, 10, 4, 4])),
            (1usize, serde_json::json!([22, 22, 4, 4])),
        ] {
            let (status, action) = post_test_action(
                &server,
                serde_json::json!({"id":"TPL_SHAPE","candidate_index":index}),
            );
            assert!(status.contains("200"), "{status} {action}");
            assert_eq!(
                action["action_box"], cands[index]["action_box"],
                "test_action and candidates disagree: {action} vs {v}"
            );
            assert_eq!(action["action_box"], expected, "{action}");
        }
    }

