    #[test]
    fn install_refuses_a_legacy_package_schema() {
        // V2.0 (design §6.3): `package_schema=1` packages are refused loudly and
        // the user must re-publish with the V2 variable model.
        let td = TempDir::new("legacy-package");
        let src = td.path().join("src/tasks");
        std::fs::create_dir_all(&src).unwrap();
        pkg_write_task(&src, "A", 1, "[]", PKG_FINISH);
        let pkg = pkg_build(
            &src,
            &td.path().join("src/assets"),
            "A",
            false,
            &td.path().join("dist"),
        );
        let legacy = td.path().join("legacy-v1.oaspkg");
        rewrite_package(&pkg.path, &legacy, |archive| {
            archive.manifest.package_schema = 1;
        });
        let runner = runner_pkg_server(td.path());
        let (status, body) = install_pkg(&runner, &legacy, false);
        assert!(status.contains("400"), "{status} {body}");
        assert!(body.contains("unsupported package_schema 1"), "{body}");
        assert!(body.contains("re-publish"), "{body}");
        assert!(!td.path().join("runner/tasks/A").exists());
        // The V2 package from the same source still installs.
        let (status, body) = install_pkg(&runner, &pkg.path, false);
        assert!(status.contains("200"), "{status} {body}");
    }

    #[test]
    fn activate_restores_an_uninstalled_task_from_the_latest_backup() {
        let td = TempDir::new("activate-uninstalled");
        let src = td.path().join("src/tasks");
        std::fs::create_dir_all(&src).unwrap();
        let runner = runner_pkg_server(td.path());
        for version in [1u32, 2] {
            pkg_write_task(&src, "A", version, "[]", PKG_FINISH);
            let pkg = pkg_build(
                &src,
                &td.path().join("src/assets"),
                "A",
                false,
                &td.path().join(format!("dist-v{version}")),
            );
            assert!(install_pkg(&runner, &pkg.path, false).0.contains("200"));
        }
        // The uninstall backup must sort strictly after the install backups.
        std::thread::sleep(std::time::Duration::from_millis(5));
        let (status, body) = post_route(
            &runner,
            "/runner/uninstall",
            "application/json",
            br#"{"task_id":"A"}"#,
        );
        assert!(status.contains("200"), "{status} {body}");
        let uninstall_backup =
            serde_json::from_str::<serde_json::Value>(&body).unwrap()["backup"]
                .as_str()
                .unwrap()
                .to_string();
        assert!(
            uninstall_backup.starts_with("backup/uninstall-A-"),
            "{uninstall_backup}"
        );
        assert!(!td.path().join("runner/tasks/A").exists());

        // No installed.json entry: activate restores the newest backup.
        let (status, body) = post_route(
            &runner,
            "/runner/packages/activate",
            "application/json",
            br#"{"task_id":"A"}"#,
        );
        assert!(status.contains("200"), "{status} {body}");
        let v: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(v["version"], 2);
        assert_eq!(v["restored_from"], uninstall_backup.as_str());
        assert!(v["package_id"].as_str().unwrap().starts_with("pkg-A-2-"));
        let meta = std::fs::read_to_string(td.path().join("runner/tasks/A/meta.json")).unwrap();
        assert!(meta.contains("\"version\":2"), "{meta}");
        let installed = package_cmd::read_installed(&td.path().join("runner/packages")).unwrap();
        let entry = installed.find("A").expect("registry entry restored");
        assert_eq!(entry.version, 2);
        assert!(entry.package_id.starts_with("pkg-A-2-"));
        assert!(entry.backup.is_none());

        // Unknown task -> 404 (nothing to restore).
        let (status, body) = post_route(
            &runner,
            "/runner/packages/activate",
            "application/json",
            br#"{"task_id":"Nope"}"#,
        );
        assert!(status.contains("404"), "{status} {body}");
    }

    #[test]
    fn activate_rejects_backups_outside_backup_or_owned_by_another_task() {
        let td = TempDir::new("activate-owner");
        let src = td.path().join("src/tasks");
        std::fs::create_dir_all(&src).unwrap();
        let runner = runner_pkg_server(td.path());
        for id in ["A", "B"] {
            pkg_write_task(&src, id, 1, "[]", PKG_FINISH);
            let pkg = pkg_build(
                &src,
                &td.path().join("src/assets"),
                id,
                false,
                &td.path().join("dist"),
            );
            assert!(install_pkg(&runner, &pkg.path, false).0.contains("200"));
        }
        let (status, body) = post_route(
            &runner,
            "/runner/uninstall",
            "application/json",
            br#"{"task_id":"B"}"#,
        );
        assert!(status.contains("200"), "{status} {body}");
        let b_backup = serde_json::from_str::<serde_json::Value>(&body).unwrap()["backup"]
            .as_str()
            .unwrap()
            .to_string();

        // B's backup must not be able to replace A.
        let request = serde_json::json!({"task_id":"A","backup": b_backup}).to_string();
        let (status, body) = post_route(
            &runner,
            "/runner/packages/activate",
            "application/json",
            request.as_bytes(),
        );
        assert!(status.contains("400"), "{status} {body}");
        assert!(body.contains("belongs to task"), "{body}");
        assert!(td.path().join("runner/tasks/A/meta.json").is_file());
        assert!(!td.path().join("runner/tasks/B").exists());

        // A path outside `backup/` is refused before touching anything.
        let request = serde_json::json!({"task_id":"A","backup":"staging/not-a-backup"}).to_string();
        let (status, body) = post_route(
            &runner,
            "/runner/packages/activate",
            "application/json",
            request.as_bytes(),
        );
        assert!(status.contains("400"), "{status} {body}");
        assert!(body.contains("backup/"), "{body}");

        // B's own backup restores B (the ownership check is not a blanket ban).
        let request = serde_json::json!({"task_id":"B","backup": b_backup}).to_string();
        let (status, body) = post_route(
            &runner,
            "/runner/packages/activate",
            "application/json",
            request.as_bytes(),
        );
        assert!(status.contains("200"), "{status} {body}");
        assert!(td.path().join("runner/tasks/B/meta.json").is_file());
    }

    // -----------------------------------------------------------------------
    // P0-1a: Studio → Runner publish exchange (GET /runner/updates & ack/notify)
    // -----------------------------------------------------------------------

    /// Exchange-enabled server for either surface: the exchange dir and the
    /// seen store are both pinned under the test tempdir.
    fn exchange_server(td: &Path, surface: Surface) -> Server {
        let server = match surface {
            Surface::Studio => studio_pkg_server(td),
            Surface::Runner => runner_pkg_server(td),
        };
        server
            .with_exchange(true, td.join("exchange"))
            .with_notifications_path(td.join("config/notifications.json"))
            .with_editor_log(td.join("logs/editor.log"))
    }

    fn test_publish_event(
        id: &str,
        task: &str,
        version: u32,
        package_file: &str,
        published_at_ms: u64,
    ) -> exchange::PublishEvent {
        exchange::PublishEvent {
            event_id: id.to_string(),
            task_id: task.to_string(),
            task_version: version,
            package_id: id.to_string(),
            package_file: package_file.to_string(),
            sha256: "a".repeat(64),
            size_bytes: 3,
            published_at_ms,
            source: None,
            min_engine: None,
            flow_ops: Vec::new(),
            package_url: None,
        }
    }

    fn write_test_index(exchange_dir: &Path, events: Vec<exchange::PublishEvent>) {
        std::fs::create_dir_all(exchange_dir).expect("create exchange dir");
        let mut index = exchange::PublishIndex::default();
        index.events = events;
        index.seq = 1;
        exchange::write_index(exchange_dir, &index).expect("write test index");
    }

    #[test]
    fn exchange_routes_are_runner_only_and_the_ack_store_persists() {
        assert_eq!(
            route_owner("GET", "/runner/updates"),
            Some(RouteOwner::Runner)
        );
        assert_eq!(
            route_owner("POST", "/runner/updates/ack"),
            Some(RouteOwner::Runner)
        );
        assert_eq!(
            route_owner("POST", "/runner/notify"),
            Some(RouteOwner::Runner)
        );
        assert_eq!(
            required_surface("GET", "/runner/updates"),
            Some(Surface::Runner)
        );

        let td = TempDir::new("exchange-surface");
        let studio = exchange_server(td.path(), Surface::Studio);
        // Studio gets a plain 404 (the routes must not even leak their shape).
        let (status, body) = get_route(&studio, "/runner/updates");
        assert!(status.contains("404"), "studio /runner/updates: {status} {body}");
        for (target, payload) in [
            (
                "/runner/updates/ack",
                &br#"{"event_ids":["pkg-x"],"status":"dismissed"}"#[..],
            ),
            ("/runner/notify", &br#"{"event_id":"x"}"#[..]),
        ] {
            let (status, body) = post_route(&studio, target, "application/json", payload);
            assert!(status.contains("404"), "studio {target}: {status} {body}");
        }

        let runner = exchange_server(td.path(), Surface::Runner);
        // Empty exchange (no index yet) = enabled + empty list, never an error.
        let (status, body) = get_route(&runner, "/runner/updates");
        assert!(status.contains("200"), "{status} {body}");
        let v: serde_json::Value = serde_json::from_str(&body).expect("updates JSON");
        assert_eq!(v["ok"], true);
        assert_eq!(v["enabled"], true);
        assert_eq!(
            v["exchange_dir"],
            td.path().join("exchange").display().to_string()
        );
        assert_eq!(v["updates"], serde_json::json!([]));
        assert!(v["last_scan_ms"].as_u64().unwrap() > 0);
        assert!(v.get("error").is_none(), "no error for a missing index: {v}");

        let (status, body) = post_route(
            &runner,
            "/runner/updates/ack",
            "application/json",
            br#"{"event_ids":["pkg-x"],"status":"dismissed"}"#,
        );
        assert!(status.contains("200"), "{status} {body}");
        let v: serde_json::Value = serde_json::from_str(&body).expect("ack JSON");
        assert_eq!(v["ok"], true);
        assert!(v["updated_ms"].as_u64().unwrap() > 0);
        // The Runner-local seen store is schema v1 and honors the ACK.
        let stored = read_json(&td.path().join("config/notifications.json"));
        assert_eq!(stored["schema_version"], 1);
        assert_eq!(stored["seen"]["pkg-x"]["status"], "dismissed");
        assert!(stored["seen"]["pkg-x"]["updated_ms"].as_u64().unwrap() > 0);

        let (status, body) = post_route(
            &runner,
            "/runner/notify",
            "application/json",
            br#"{"event_id":"pkg-x"}"#,
        );
        assert!(status.contains("200"), "{status} {body}");
        let v: serde_json::Value = serde_json::from_str(&body).expect("notify JSON");
        assert_eq!(v["ok"], true);
        assert_eq!(v["accepted"], true);
    }

    #[test]
    fn runner_notify_accepts_empty_or_object_and_rejects_other_json() {
        let td = TempDir::new("exchange-notify");
        let runner = exchange_server(td.path(), Surface::Runner);
        // An empty body is a valid "just wake up" hint.
        let (status, body) = post_route(&runner, "/runner/notify", "application/json", b"");
        assert!(status.contains("200"), "{status} {body}");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&body).unwrap()["accepted"],
            true
        );
        for bad in [&br#"[1,2]"#[..], &br#""text""#[..], &br#"{ broken"#[..]] {
            let (status, body) = post_route(&runner, "/runner/notify", "application/json", bad);
            assert!(status.contains("400"), "{status} {body}");
        }
    }

